arguments:
$ErrorActionPreference = 'SilentlyContinue'
$since = [datetime]'2026-09-04T15:14:00'
'=== PROCESS ==='
Get-Process | Where-Object { $_.ProcessName -match 'Cinebench|Cinema|Maxon' } | Select-Object Id,ProcessName,SessionId,StartTime,Path | Format-List
'=== EXECUTABLE ==='
$exe = 'C:\Assets\Cinebench2026\Cinebench.exe'
Get-Item -LiteralPath $exe | Select-Object FullName,Length,LastWriteTime,@{Name='FileVersion';Expression={$_.VersionInfo.FileVersion}},@{Name='ProductVersion';Expression={$_.VersionInfo.ProductVersion}} | Format-List
Get-FileHash -LiteralPath $exe -Algorithm SHA256 | Format-List
Get-AuthenticodeSignature -LiteralPath $exe | Select-Object Status,StatusMessage,SignerCertificate | Format-List
'=== RECENT_FILES ==='
$roots = @('C:\Assets\Cinebench2026','C:\Users\Song\AppData\Roaming\Maxon','C:\Users\Song\AppData\Local\Maxon','C:\Users\Song\Documents\MAXON','C:\ProgramData\Maxon')
$recent = @()
foreach ($root in $roots) {
 if (Test-Path -LiteralPath $root) {
  $recent += Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.LastWriteTime -ge $since }
 }
}
$recent | Sort-Object LastWriteTime -Descending | Select-Object -First 80 Name,Length,LastWriteTime,FullName | Format-List
'=== BROKEN_OR_ERROR_TEXT ==='
foreach ($file in ($recent | Where-Object { $_.Length -le 2097152 -and $_.Extension -match '^\.(txt|log|json|xml|ini|cfg)$' })) {
 $matches = Select-String -LiteralPath $file.FullName -Pattern 'binary','broken','corrupt','error','failed','exception' -SimpleMatch
 if ($matches) {
  Write-Output ('FILE=' + $file.FullName)
  $matches | Select-Object -First 30 | ForEach-Object { $_.Line }
 }
}
'=== APPLICATION_EVENTS ==='
Get-WinEvent -FilterHashtable @{LogName='Application';StartTime=$since} -MaxEvents 100 | Where-Object { $_.ProviderName -match 'Cinebench|Maxon|Application Error|Windows Error Reporting' -or $_.Message -match 'Cinebench|Maxon|binary file|broken' } | Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,Message | Format-List
exit 0
